INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (2, 22, 'linechart', '{"w":4,"h":4,"x":3,"y":1,"i":"1","moved":false,"static":false}', 'Total Transactions by Application (click on the app name to filter)', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"FROM Transaction SELECT count(*) FACET appName","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (3, 22, 'linechart', '{"w":4,"h":4,"x":7,"y":1,"i":"2","moved":false,"static":false}', 'Memory Allocation/Working Set (MB)', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(newrelic.timeslice.value) * 1e+6 AS ''Memory Working Set'' FROM Metric WHERE metricTimesliceName LIKE ''%Memory/WorkingSet%'' TIMESERIES AUTO ","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (4, 22, 'linechart', '{"w":2,"h":4,"x":11,"y":1,"i":"3","moved":false,"static":false}', 'HTTP Status Code', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT apdex(newrelic.timeslice.value) FROM Metric WHERE metricTimesliceName LIKE ''Apdex/StatusCode/%'' FACET metricTimesliceName","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (5, 22, 'linechart', '{"w":2,"h":3,"x":1,"y":3,"i":"4","moved":false,"static":false}', NULL, 'active', '{"query":"","unit":"number","queries":[],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (6, 22, 'linechart', '{"w":5,"h":4,"x":3,"y":5,"i":"5","moved":false,"static":false}', 'Slowest Query Time', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(apm.service.datastore.operation.duration * 1000) FROM Metric WHERE datastoreType = ''MSSQL'' AND `table` != '''' AND `table` != ''(subquery)'' FACET `datastoreType`, `table`, `operation` LIMIT 5 TIMESERIES ","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (7, 22, 'linechart', '{"w":5,"h":4,"x":8,"y":5,"i":"6","moved":false,"static":false}', 'Most Time Consuming', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT sum(apm.service.datastore.operation.duration * 1000) FROM Metric  FACET `datastoreType`, `table`, `operation` LIMIT 5 TIMESERIES WHERE datastoreType = ''MSSQL'' AND `table` != '''' AND `table` != ''(subquery)''","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (8, 22, 'linechart', '{"w":2,"h":3,"x":1,"y":6,"i":"7","moved":false,"static":false}', 'CPU Utilization', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(newrelic.timeslice.value) * 1000 FROM Metric WHERE metricTimesliceName LIKE ''%CPU/%'' FACET metricTimesliceName","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (9, 22, 'linechart', '{"w":2,"h":3,"x":1,"y":9,"i":"8","moved":false,"static":false}', 'Apdex Score', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT apdex(apm.service.apdex) as ''App server'', apdex(apm.service.apdex.user) as ''End user'' FROM Metric LIMIT MAX","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (10, 22, 'linechart', '{"w":4,"h":3,"x":3,"y":9,"i":"9","moved":false,"static":false}', 'Memory Used by Large Object Heap', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(newrelic.timeslice.value) * 1e+6 AS `GC/LOH/Size(MB)` FROM Metric WHERE metricTimesliceName LIKE ''GC/LOH/Size%'' TIMESERIES","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
