INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (26, 16, 'linechart', '{"w":7,"h":3,"x":6,"y":1,"i":"1","moved":false,"static":false}', 'Most Popular Incoming HTTP Requests', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT count(*) FROM Transaction WHERE (transactionType = ''Web'') SINCE last week EXTRAPOLATE FACET name","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (27, 16, 'linechart', '{"w":4,"h":3,"x":1,"y":4,"i":"2","moved":false,"static":false}', 'Slowest Average Response Time', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/ROOT'')) as ''ROOT'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/StatusCode/302'')) as ''302'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/Basket/Checkout'')) as ''Basket/Checkout'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/Basket'')) as ''Basket'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/images/products/1.png'')) as ''images/products/1.png'' FROM Metric WHERE (transactionType = ''Web'') LIMIT 5 TIMESERIES","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (28, 16, 'linechart', '{"w":4,"h":3,"x":5,"y":4,"i":"3","moved":false,"static":false}', 'Web Transactions Time', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT filter(average(apm.service.overview.web * 1000), WHERE segmentName like ''.NET'') as ''.NET'', filter(average(apm.service.overview.web * 1000), WHERE segmentName like ''MSSQL'') as ''MSSQL'' FROM Metric LIMIT MAX TIMESERIES AUTO","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (29, 16, 'linechart', '{"w":4,"h":3,"x":9,"y":4,"i":"4","moved":false,"static":false}', 'Top 5 Slowest Transactions', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT max(duration) FROM Transaction WHERE (transactionType = ''Web'') SINCE 1 week ago LIMIT 5 EXTRAPOLATE FACET name","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (30, 16, 'linechart', '{"w":5,"h":3,"x":1,"y":7,"i":"5","moved":false,"static":false}', 'Throughput Today Compared With 1 Week Ago', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT count(*) from Transaction TIMESERIES 1 hour since today COMPARE WITH 1 week ago","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (31, 16, 'linechart', '{"w":5,"h":3,"x":6,"y":7,"i":"6","moved":false,"static":false}', 'Middleware Pipeline', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(newrelic.timeslice.value) * 1000 AS `DotNet/OrderController/Detail` FROM Metric WHERE metricTimesliceName LIKE ''DotNet/%'' FACET metricTimesliceName TIMESERIES","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (32, 16, 'linechart', '{"w":2,"h":3,"x":11,"y":7,"i":"7","moved":false,"static":false}', 'Transactions Overview', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"FROM Transaction SELECT count(*) as ''Total transactions'', average(duration) as ''Avg duration (s)'', percentile(duration, 90) as ''Slowest 10% (s)'', percentage(count(*), WHERE error is false) AS ''Success rate''","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (33, 16, 'linechart', '{"w":4,"h":3,"x":1,"y":10,"i":"8","moved":false,"static":false}', 'Transactions Day By Day ', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"FROM Transaction SELECT count(*), percentage(count(*), WHERE error IS false) FACET dateOf(timestamp) TIMESERIES AUTO ","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (34, 16, 'linechart', '{"w":4,"h":3,"x":5,"y":10,"i":"9","moved":false,"static":false}', 'Average Transaction Duration Today Compared With 1 Week Ago', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT average(duration) FROM Transaction TIMESERIES SINCE today COMPARE WITH 1 week ago","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
