INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (38, 17, 'linechart', '{"w":4,"h":3,"x":5,"y":3,"i":"2","moved":false,"static":false}', 'Transaction Errors Day By Day', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"FROM TransactionError SELECT count(*), percentage(count(*), WHERE error IS true) FACET dateOf(timestamp) SINCE 1 week ago","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
