INSERT INTO panels (id, dashboard_id, type, layout, title, status, config, created_at, updated_at) VALUES (86, 22, 'linechart', '{"w":4,"h":3,"x":1,"y":4,"i":"2","moved":false,"static":false}', 'Slowest Average Response Time', 'active', '{"query":"","unit":"number","queries":[{"title":"","query":"SELECT filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/ROOT'')) as ''ROOT'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/StatusCode/302'')) as ''302'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/Basket/Checkout'')) as ''Basket/Checkout'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/Basket'')) as ''Basket'', filter(rate(sum(apm.service.transaction.duration), 1 second), WHERE transactionName IN (''WebTransaction/ASP/images/products/1.png'')) as ''images/products/1.png'' FROM Metric WHERE (transactionType = ''Web'') LIMIT 5 TIMESERIES","unit":"number","model":{"type":"quick","calculate":"rpm","value":"90","labelPairs":[{"label":"","operator":"=","values":[],"options":[]}],"groupBy":[]}}],"legend":{"pos":"right","label":[],"formula":"avg"},"stack":false,"showSearch":false}', '2025-07-17 19:58:42', '2025-07-17 19:58:42');
